package app.rwun;
import android.content.Context;import java.time.*;import java.util.*;import org.json.*;
/** Reviewed original recording; calendar dates never become invented recording timestamps. */
record HealthWritePlan(String id,String title,boolean walking,boolean indoor,Instant start,Instant end,long activeSeconds,Double km,String distanceSource){
 HealthWritePlan {long elapsed=Duration.between(start,end).getSeconds();if(id.isBlank()||id.length()>210||!end.isAfter(start)||start.toEpochMilli()<=0||end.isAfter(Instant.now().plusSeconds(5))||elapsed>7*86400||activeSeconds<1||activeSeconds>180000||activeSeconds>elapsed+1)throw new IllegalArgumentException("This recording has no reliable start/end timestamps for Health Connect.");if(km!=null&&(!Double.isFinite(km)||km<=0||km>250))throw new IllegalArgumentException("This recording has no valid distance for export.");}
 String fingerprint(){return RaceData.digest(id+"|"+title+"|"+walking+"|"+indoor+"|"+start+"|"+end+"|"+activeSeconds+"|"+km+"|"+distanceSource);}
 String summary(){return title+"\n"+start+" to "+end+" (UTC)\n"+activeSeconds/60+"m "+activeSeconds%60+"s active · "+Duration.between(start,end).getSeconds()/60+"m elapsed, including pauses\n"+(km==null?"Time only · no distance record will be written":PlanEngine.distance(km)+" · "+distanceSource)+"\n\nWrites an exercise session"+(km==null?".":" and distance.")+" Routes, heart-rate samples, steps and training feedback are not written. Repeating updates the same records. Removing local history does not delete Health Connect records.";}
 static List<HealthWritePlan> available(Context c,RunStore store){List<HealthWritePlan> out=new ArrayList<>();for(var r:store.runs())if(r.source().equals("GPS"))add(out,()->gps(c,store,r.sessionId(),false));JSONArray walks=store.walks();for(int i=0;i<walks.length();i++){JSONObject r=walks.optJSONObject(i);if(r!=null&&r.optString("recordedSource",r.optString("source")).equals("GPS")){String id=r.optString("id");add(out,()->gps(c,store,id,true));}}JSONArray indoor=store.v103().optJSONArray("indoor");if(indoor!=null)for(int i=0;i<indoor.length();i++){JSONObject r=indoor.optJSONObject(i);if(r!=null)add(out,()->indoor(r));}out.sort(Comparator.comparing(HealthWritePlan::start).reversed());return List.copyOf(out);}
 static HealthWritePlan find(Context c,RunStore store,String id){if(id.startsWith("indoor:")){JSONArray rows=store.v103().optJSONArray("indoor");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&id.equals("indoor:"+r.optString("id")))return indoor(r);}}else{for(var r:store.runs())if(r.sessionId().equals(id))return gps(c,store,id,false);JSONArray rows=store.walks();for(int i=0;i<rows.length();i++)if(rows.optJSONObject(i)!=null&&id.equals(rows.optJSONObject(i).optString("id")))return gps(c,store,id,true);}throw new IllegalArgumentException("This recording is no longer available. Choose another activity.");}
 private static HealthWritePlan gps(Context c,RunStore store,String id,boolean walking){double km=0;long seconds=0;String route="",source="",distanceSource="GPS";if(walking){JSONArray rows=store.walks();for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&id.equals(r.optString("id"))){source=r.optString("recordedSource",r.optString("source"));route=r.optString("route");km=r.optDouble("km");seconds=r.optLong("seconds");distanceSource=r.optString("source").equals("Manual walk distance")?"Manually corrected distance":"GPS";}}}else for(var r:store.runs())if(id.equals(r.sessionId())){source=r.source();route=r.routeFile();km=r.km();seconds=r.seconds();}
  if(!source.equals("GPS")||route.isEmpty())throw new IllegalArgumentException("Only original OpenRun recordings can be written; imported activities are excluded.");
  try{var points=TrackingService.readRoute(c,route);if(points.size()<2)throw new IllegalArgumentException("This recording has no usable timestamped route.");long begun=points.get(0).time(),ended=points.get(points.size()-1).time();JSONObject origins=store.v103().optJSONObject("importOrigins"),origin=origins==null?null:origins.optJSONObject(id);if(origin!=null&&origin.optString("provider").equals("OpenRun GPS")&&origin.optLong("started")>0&&origin.optLong("ended")>origin.optLong("started")){begun=origin.optLong("started");ended=origin.optLong("ended");}return new HealthWritePlan(id,walking?"OpenRun · Outdoor walk":"OpenRun · Outdoor run",walking,false,Instant.ofEpochMilli(begun),Instant.ofEpochMilli(ended),seconds,km>0?km:null,distanceSource);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("The saved route could not be read. Local history is unchanged.",e);}}
 private static HealthWritePlan indoor(JSONObject r){boolean walk=r.optString("kind").equals("Walk");if(!walk&&!r.optString("kind").equals("Run"))throw new IllegalArgumentException("Unsupported activity type");return new HealthWritePlan("indoor:"+r.optString("id"),walk?"OpenRun · Indoor walk":"OpenRun · Treadmill run",walk,true,Instant.ofEpochMilli(r.optLong("startedAtWall")),Instant.ofEpochMilli(r.optLong("endedAtWall")),r.optLong("seconds"),r.isNull("km")?null:r.optDouble("km"),r.optString("distanceSource","Machine entered"));}
 private interface Loader{HealthWritePlan get();}private static void add(List<HealthWritePlan> out,Loader loader){try{out.add(loader.get());}catch(IllegalArgumentException unusable){/* Keep older records local without fabricating times. */}}
}
